55	    _abortSignal: AbortSignal,
56	  ): Promise<ToolCallConfirmationDetails | false> {
57	    if (!this.messageBus) {
58	      return false;
59	    }
60	
61	    return {
62	      type: 'mcp',
63	      title: `Confirm MCP Tool: ${this.toolName}`,
64	      serverName: 'browser-agent',
65	      toolName: this.toolName,
66	      toolDisplayName: this.toolName,
67	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
68	        await this.publishPolicyUpdate(outcome);
69	      },
70	    };
71	  }
