81	  async execute(signal: AbortSignal): Promise<ToolResult> {
82	    try {
83	      const callToolPromise = this.browserManager.callTool(
84	        this.toolName,
85	        this.params,
86	        signal,
87	      );
88	
89	      const result: McpToolCallResult = await callToolPromise;
90	
91	      // Extract text content from MCP response
92	      let textContent = '';
93	      if (result.content && Array.isArray(result.content)) {
94	        textContent = result.content
95	          .filter((c) => c.type === 'text' && c.text)
96	          .map((c) => c.text)
97	          .join('\n');
98	      }
99	
100	      // Post-process to add contextual hints for common error patterns
101	      const processedContent = postProcessToolResult(
102	        this.toolName,
103	        textContent,
104	      );
105	
106	      if (result.isError) {
107	        return {
108	          llmContent: `Error: ${processedContent}`,
109	          returnDisplay: `Error: ${processedContent}`,
110	          error: { message: textContent },
111	        };
112	      }
113	
114	      return {
115	        llmContent: processedContent || 'Tool executed successfully.',
116	        returnDisplay: processedContent || 'Tool executed successfully.',
117	      };
118	    } catch (error) {
119	      const errorMsg = error instanceof Error ? error.message : String(error);
120	
121	      // Chrome connection errors are fatal — re-throw to terminate the agent
122	      // immediately instead of returning a result the LLM would retry.
123	      if (errorMsg.includes('Could not connect to Chrome')) {
124	        throw error;
125	      }
126	
127	      debugLogger.error(`MCP tool ${this.toolName} failed: ${errorMsg}`);
128	      return {
129	        llmContent: `Error: ${errorMsg}`,
130	        returnDisplay: `Error: ${errorMsg}`,
131	        error: { message: errorMsg },
132	      };
133	    }
134	  }
