/**
 * @fileoverview Input-blocking overlay utilities for automated browser control.
 *
 * While the browser agent performs an interactive operation, human input on the
 * page can race with the automation (e.g. a stray click landing between the
 * agent's snapshot and its click). To prevent this, we inject a full-viewport
 * overlay that captures pointer/keyboard input and displays a notice that the
 * browser is under agent control.
 *
 * The overlay is temporarily suspended around each individual interactive tool
 * call (so the agent's own action reaches the page) and resumed afterwards, then
 * removed entirely once the operation completes — even if it fails.
 *
 * The script strings are passed to chrome-devtools-mcp's evaluate_script tool
 * which expects a plain function expression (NOT an IIFE). Nested template
 * literals are avoided by using string concatenation.
 */

import type { BrowserManager } from './browserManager.js';
import { debugLogger } from '../../utils/debugLogger.js';

const INPUT_BLOCKER_ELEMENT_ID = '__gemini_input_blocker';

const INPUT_BLOCKER_NOTICE = 'Gemini CLI is controlling this browser';

/**
 * Builds the JavaScript function string that injects the input-blocking overlay.
 *
 * Returns a plain arrow-function expression (no trailing invocation) because
 * chrome-devtools-mcp's evaluate_script tool invokes it internally.
 */
function buildInjectionScript(): string {
  return `() => {
    const id = '${INPUT_BLOCKER_ELEMENT_ID}';
    const existing = document.getElementById(id);
    if (existing) existing.remove();

    const blocker = document.createElement('div');
    blocker.id = id;
    blocker.setAttribute('aria-hidden', 'true');
    blocker.setAttribute('role', 'presentation');

    Object.assign(blocker.style, {
      position: 'fixed',
      top: '0',
      left: '0',
      right: '0',
      bottom: '0',
      zIndex: '2147483647',
      pointerEvents: 'auto',
      cursor: 'not-allowed',
      display: 'flex',
      alignItems: 'flex-start',
      justifyContent: 'center',
      background: 'transparent',
    });

    const label = document.createElement('div');
    label.textContent = '${INPUT_BLOCKER_NOTICE}';
    Object.assign(label.style, {
      marginTop: '12px',
      padding: '6px 12px',
      borderRadius: '4px',
      background: 'rgba(66,133,244,0.95)',
      color: '#fff',
