function buildRemovalScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.remove();
    return 'input-blocker-removed';
  }`;
}

/**
 * Builds the JavaScript function string that temporarily suspends the
 * input-blocking overlay so an automated interactive action can reach the page.
 */
export function buildSuspendScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.display = 'none';
    return 'input-blocker-suspended';
  }`;
}

/**
 * Builds the JavaScript function string that resumes a previously-suspended
 * input-blocking overlay.
 */
export function buildResumeScript(): string {
  return `() => {
    const el = document.getElementById('${INPUT_BLOCKER_ELEMENT_ID}');
    if (el) el.style.display = 'flex';
    return 'input-blocker-resumed';
  }`;
}

/**
 * Injects the input-blocking overlay into the current page.
 *
 * Errors from the underlying tool call are swallowed and the promise resolves
 * with `undefined` — blocking user input is best-effort and must never break
 * the operation it protects.
