export async function injectInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Injecting input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildInjectionScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to inject input blocker:', result);
    } else {
      debugLogger.log('Input blocker injected successfully');
    }
  } catch (error) {
    debugLogger.warn('Error injecting input blocker:', error);
    return undefined;
  }
}

/**
 * Removes the input-blocking overlay from the current page.
 *
 * Errors from the underlying tool call are swallowed and the promise resolves
 * with `undefined` so removal always succeeds from the caller's perspective,
 * even when the operation it protected has failed.
 */
export async function removeInputBlocker(
  browserManager: BrowserManager,
  signal?: AbortSignal,
): Promise<void> {
  try {
    debugLogger.log('Removing input blocker...');

    const result = await browserManager.callTool(
      'evaluate_script',
      { function: buildRemovalScript() },
      signal,
    );

    if (result.isError) {
      debugLogger.warn('Failed to remove input blocker:', result);
    } else {
      debugLogger.log('Input blocker removed successfully');
    }
  } catch (error) {
    debugLogger.warn('Error removing input blocker:', error);
    return undefined;
  }
}

/**
 * Set of chrome-devtools-mcp tools that mutate page state via simulated user
 * input. These are the tools whose execution should be bracketed by suspend /
 * resume of the input blocker. Read-only tools (take_snapshot, take_screenshot,
 * list_pages, evaluate_script, etc.) are intentionally excluded.
 */
export const INTERACTIVE_TOOL_NAMES: ReadonlySet<string> = new Set([
  'click',
  'click_at',
  'drag',
  'fill',
  'fill_form',
  'handle_dialog',
  'hover',
  'press_key',
  'upload_file',
]);

/**
 * Returns true when the given tool simulates user input and should therefore be
 * wrapped with suspend/resume of the input blocker.
 */
export function isInteractiveTool(toolName: string): boolean {
  return INTERACTIVE_TOOL_NAMES.has(toolName);
}
